// Trello on an API key and token: every operation of Trello's REST API. actions.json is generated by
// `bun scripts/openapi-actions.ts trello`; what happens on a board or workspace starts automations by webhook (triggers.ts).
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, rest, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

// the connection's key is "KEY:TOKEN": the Power-Up's API key and the token made for it
export const split = (secret: string) => {
  const at = secret.indexOf(":");
  if (at < 0) return { key: secret.trim(), token: "" };
  return { key: secret.slice(0, at).trim(), token: secret.slice(at + 1).trim() };
};

const api: Api = {
  name: "Trello",
  base: "https://api.trello.com/1",
  tokenHelp: "trello.com/power-ups/admin → your Power-Up → API key → Token",
  auth: (secret) => {
    const { key, token } = split(secret);
    return { Authorization: `OAuth oauth_consumer_key="${key}", oauth_token="${token}"` };
  },
};

const ME = { method: "GET", path: "/members/me", query: ["fields"], headers: [] };

const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);
// calls about the connection's own token (or key) get it filled in, so no agent ever sees or types it
for (const { name, fill } of (await Bun.file(file).json()).actions as { name: string; fill?: string[] }[]) {
  if (!fill) continue;
  const action = actions[name]!;
  const run = action.run;
  action.run = (input: Record<string, unknown>, secret) => run({ ...input, ...Object.fromEntries(fill.map((f) => [f, split(secret)[f as "key" | "token"]])) }, secret);
}

// any route of the API, for the older ones Trello still answers but no longer lists in its spec (deltas, display, membersInvited, single-field updates)
const ROUTE = {
  path: z.string().describe("The route after api.trello.com/1, like /boards/{board id}/membersInvited or /actions/{id}/display"),
  query: z.record(z.string(), z.any()).optional().describe("Its parameters, like {\"fields\": \"name,url\"}"),
};
const anyRoute = (method: string, i: { path: string; query?: Record<string, unknown> }, secret: string) => {
  if (!/^\/[\w\-./]*$/.test(i.path) || i.path.includes("..")) throw new AppsError("path: a Trello route like /boards/5f.../cards");
  const query = i.query ?? {};
  return call(api, secret, { method, path: i.path, query: Object.keys(query), headers: [] }, query);
};

const loose = (fields: Record<string, z.ZodType>) => z.object(fields).loose();

export const trello: OwnApp = {
  app: "trello",
  name: "Trello",
  logo: "/logos/trello.svg",
  keyField: {
    label: "API key and token",
    help: "1. Open trello.com/power-ups/admin and click New (any name, like Emplio; any workspace) and Create. 2. Open API key → Generate a new API key, and copy the API key. 3. Click the Token link next to it, choose Allow, and copy the token. 4. Paste both here as KEY:TOKEN (the key, a colon, then the token). Emplio can then do whatever your Trello account can.",
    placeholder: "API key:token",
  },
  async check(secret) {
    const { key, token } = split(secret);
    if (!key || !token) throw new AppsError("paste the API key and the token together, as KEY:TOKEN (a colon between them)");
    const me = (await call(api, secret, ME, { fields: "fullName,username" })) as { id: string; fullName?: string; username?: string };
    return me.fullName || me.username || me.id;
  },
  push: {
    events,
    triggers,
    start: (secret, connection, event, config) => watch(api, secret, split(secret).token, connection, event, config),
    stop: (secret, id) => unwatch(api, secret, split(secret).token, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions: {
    ...actions,
    // Composio's names for the same calls, so saved automations carry over
    get_members_me: rest(api, "GET", "/members/me", "Who the connected Trello account is: name, username, and the ids of its boards and workspaces. Fields like fields=fullName,username narrow the answer.", loose({ fields: z.string().optional().describe("Which fields to give back, comma separated, like fullName,username,idBoards; all if left out") })),
    who_am_i: rest(api, "GET", "/members/me", "Who the connected Trello account is (same as get_members_me).", loose({})),
    get_members_me_boards: rest(api, "GET", "/members/me/boards", "The boards the connected Trello account can see, with their ids and links. Most other calls need a board's id from here.", loose({
      filter: z.string().optional().describe("all (default), open, closed, members, organization, public, starred"),
      fields: z.string().optional().describe("Which fields to give back, comma separated, like name,url,closed"),
    })),
    update_cards_id_list_by_id_card: rest(api, "PUT", "/cards/{id}", "Move a card to another list (and, with idBoard, another board).", loose({
      id: z.string().describe("The card's id"),
      idList: z.string().describe("The list to move it to (its id)"),
      idBoard: z.string().optional().describe("The board that list is on, when it's another board"),
      pos: z.string().optional().describe("Where in the list: top, bottom or a number"),
    })),
    call_api_get: {
      description: "Read from any Trello API route by its path, for the few older ones no other action covers (like /actions/{id}/display, /boards/{id}/membersInvited, /members/{id}/deltas). Prefer the named actions.",
      readOnly: true,
      input: z.object(ROUTE),
      run: (i: { path: string; query?: Record<string, unknown> }, secret: string) => anyRoute("GET", i, secret),
    },
    call_api: {
      description: "Change something through any Trello API route by its path, like PUT /boards/{id}/labelNames/green. Prefer the named actions; use call_api_get to read.",
      input: z.object({ method: z.enum(["POST", "PUT", "DELETE"]).describe("POST adds, PUT changes, DELETE removes"), ...ROUTE }),
      run: (i: { method: string; path: string; query?: Record<string, unknown> }, secret: string) => anyRoute(i.method, i, secret),
    },
    download_card_attachment: {
      description: "Download a file attached to a Trello card, into the chat's computer. Links attached to a card come back as their address instead.",
      readOnly: true,
      input: z.object({ id: z.string().describe("The card's id"), idAttachment: z.string().describe("The attachment's id (get_cards_attachments_by_id_card lists them)") }),
      async run(i: { id: string; idAttachment: string }, secret: string) {
        const a = (await call(api, secret, { method: "GET", path: "/cards/{id}/attachments/{idAttachment}", query: [], headers: [] }, i)) as { name: string; fileName?: string; url: string; isUpload: boolean; mimeType?: string };
        if (!a.isUpload) return { url: a.url, name: a.name };
        const name = a.fileName || a.name;
        const path = [i.id, "attachments", i.idAttachment, "download", name].map(encodeURIComponent).join("/");
        const res = await fetch(`${api.base}/cards/${path}`, { headers: api.auth!(secret, {}) });
        if (!res.ok) throw new AppsError(`Trello: couldn't download ${name} (${res.status})`, res.status === 401);
        return new AppFile(name, a.mimeType || res.headers.get("content-type")?.split(";")[0] || "application/octet-stream", new Uint8Array(await res.arrayBuffer()));
      },
    },
  },
};
